    fun pop():Int=if(stacks.isEmpty())-1 else popAtStack(stacks.lastIndex);
    fun popAtStack(index:Int):Int{
        if(index !in stacks.indices||stacks[index].isEmpty())return -1;
        val value=stacks[index].pop();
        available.add(index);
        while(stacks.isNotEmpty()&&stacks.last().isEmpty()){
            val last=stacks.lastIndex;
            stacks.removeAt(last);
            available.remove(last)
        };
        return value
    }
}

